<script setup lang="ts">
import { useSettingStore } from '../store/modules/setting';
const setting = useSettingStore();
const options = [{value:'soft-light' as const,label:'浅色',icon:'☀'},{value:'dark' as const,label:'深色',icon:'☾'},{value:'auto' as const,label:'系统',icon:'◐'}];
</script>
<template><div class="appearance-switch" role="group" aria-label="外观"><button v-for="option in options" :key="option.value" type="button" :disabled="!setting.isReady" :aria-label="option.value==='auto'?'跟随系统外观':'切换'+option.label+'外观'" :title="option.value==='auto'?'跟随系统外观':option.label+'外观'" :aria-pressed="setting.config.uiTheme===option.value" @click="setting.setConfig('uiTheme',option.value)"><span aria-hidden="true">{{option.icon}}</span><span>{{option.label}}</span></button></div></template>
<style scoped>.appearance-switch{display:inline-flex;flex-shrink:0;gap:2px;padding:3px;border:1px solid var(--theme-border);border-radius:10px;background:var(--theme-panel-bg-muted);-webkit-app-region:no-drag}.appearance-switch button{display:flex;align-items:center;justify-content:center;gap:5px;min-height:30px;padding:0 9px;border:0;border-radius:7px;background:transparent;color:var(--theme-text-secondary);font-size:12px;cursor:pointer;white-space:nowrap}.appearance-switch button[aria-pressed=true]{background:var(--studio-surface);color:var(--theme-text-primary);box-shadow:0 1px 4px #0002}.appearance-switch button:hover{color:var(--theme-brand)}.appearance-switch button:focus-visible{outline:2px solid var(--theme-brand);outline-offset:2px}@media(max-width:1050px){.appearance-switch button{padding:0 7px}.appearance-switch button>span:last-child{display:none}}</style>
